// Separa cada mail de alerta en ofertas individuales — dispatcher por
// remitente, porque cada sitio arma el mail totalmente distinto (verificado
// contra mails reales del 2026-08-28: Indeed = 1 oferta/mail con
// empresa+puesto en el subject; Computrabajo = batch de filas markdown
// [| || || puesto || empresa || ubicación || fecha |](url); Bumeran = batch
// sin link en texto plano, requiere el html del mail).
//
// ASUNCIÓN SIN VALIDAR (igual que el split de LinkedIn de la v1): los
// nombres de campo item.json.from / item.json.subject / item.json.textHtml
// son el formato esperado del nodo Gmail en esta instancia de n8n — no se
// pudo confirmar contra una ejecución real todavía. Si "Aplicar tope de
// seguridad" reporta 0 ofertas de una fuente que sabés que llegó, revisar
// acá primero.
//
// El regex de Computrabajo se armó leyendo el texto plano real de un mail
// (vía Gmail API, no vía este nodo n8n) — la conversión HTML→texto plano
// de n8n puede diferir de la de Gmail API en espacios/formato exacto.
// Correr una vez, mirar el output de "Aplicar tope de seguridad" y ajustar
// el regex si no matchea.

function textoDe(item) {
  return item.json.textPlain || item.json.text || item.json.snippet || '';
}
function htmlDe(item) {
  return item.json.textHtml || item.json.html || '';
}
function remitenteDe(item) {
  return String(item.json.from || item.json.sender || '').toLowerCase();
}

function parsearLinkedIn(item) {
  const cuerpo = textoDe(item);
  const regexLink = /https:\/\/www\.linkedin\.com\/comm\/jobs\/view\/\d+[^\s)>\]]*/g;
  const matches = [...cuerpo.matchAll(regexLink)];
  if (matches.length === 0) return [{ link: null, texto_oferta: cuerpo.trim(), fuente: 'linkedin' }];
  const out = [];
  for (let i = 0; i < matches.length; i++) {
    const inicio = i === 0 ? 0 : matches[i - 1].index + matches[i - 1][0].length;
    const fin = matches[i].index + matches[i][0].length;
    out.push({ link: matches[i][0], texto_oferta: cuerpo.slice(inicio, fin).trim(), fuente: 'linkedin' });
  }
  return out;
}

function parsearIndeed(item) {
  // 1 oferta por mail — empresa/puesto vienen en el subject, no en el cuerpo.
  // link queda null a propósito: el link de Indeed es un redirect
  // cts.indeed.com de un solo uso, no sirve como referencia estable. El
  // dedup usa empresa+puesto (normalizarEmpresaPuesto), no el link.
  const cuerpo = textoDe(item);
  const asunto = item.json.subject || '';
  return [{ link: null, texto_oferta: (asunto + '\n\n' + cuerpo).trim(), fuente: 'indeed' }];
}

function parsearComputrabajo(item) {
  // Cada oferta del batch es una fila markdown:
  // [| || || <puesto> || <empresa> || <ubicación> || <fecha> |](url)
  const cuerpo = textoDe(item);
  const regexFila = /\[\|\s*\|\|\s*\|\|\s*([^|]+?)\s*\|\|\s*([^|]+?)\s*\|\|\s*([^|]+?)\s*\|\|\s*([^|]+?)\s*\|\]\(([^)]+)\)/g;
  const out = [];
  let m;
  while ((m = regexFila.exec(cuerpo)) !== null) {
    const puesto = m[1], empresa = m[2], ubicacion = m[3], fecha = m[4], url = m[5];
    out.push({ link: url, texto_oferta: puesto + ' — ' + empresa + ' — ' + ubicacion + ' — ' + fecha, fuente: 'computrabajo' });
  }
  if (out.length === 0) return [{ link: null, texto_oferta: cuerpo.trim(), fuente: 'computrabajo' }];
  return out;
}

function parsearBumeran(item) {
  // El texto plano NO trae links (se pierden al convertir el mail a texto
  // plano) — hace falta el html. Sin validar todavía contra el HTML real:
  // en vez de inventar una estructura, esto cae a NO_PARSEABLE (revisar a
  // mano) hasta confirmar el HTML real y escribir el split de tarjetas.
  const cuerpoHtml = htmlDe(item);
  if (!cuerpoHtml) {
    return [{ link: null, texto_oferta: '', fuente: 'bumeran', error_parseo_mail: true, detalle_error: 'Sin campo html en el item de Gmail — no se puede sacar el link de Bumeran del texto plano.' }];
  }
  return [{ link: null, texto_oferta: textoDe(item).trim(), fuente: 'bumeran', error_parseo_mail: true, detalle_error: 'Parser de Bumeran pendiente de validar contra HTML real — cae a revisión manual.' }];
}

const items = [];
for (const item of $input.all()) {
  try {
    const remitente = remitenteDe(item);
    let ofertas;
    if (remitente.includes('linkedin.com')) ofertas = parsearLinkedIn(item);
    else if (remitente.includes('indeed.com')) ofertas = parsearIndeed(item);
    else if (remitente.includes('computrabajo.com')) ofertas = parsearComputrabajo(item);
    else if (remitente.includes('bumeran.com')) ofertas = parsearBumeran(item);
    else ofertas = [{ link: null, texto_oferta: textoDe(item).trim(), fuente: 'desconocida' }];

    for (const oferta of ofertas) items.push({ json: oferta });
  } catch (e) {
    items.push({ json: { link: null, texto_oferta: '', fuente: 'error', error_parseo_mail: true, detalle_error: String((e && e.message) || e) } });
  }
}

return items;

// Tope duro de ofertas procesadas por corrida, para que un día raro (mail
// mal filtrado, alerta que trae 200 avisos) no genere una factura
// inesperada de la API de Claude. Cambiá este número si el volumen normal
// de alertas crece — es la única variable que hay que tocar.
const MAX_OFERTAS_POR_CORRIDA = 30;

const items = $input.all();
const totalDetectado = items.length;
const excedeTope = totalDetectado > MAX_OFERTAS_POR_CORRIDA;
const procesar = excedeTope ? items.slice(0, MAX_OFERTAS_POR_CORRIDA) : items;

// El flag va en todos los items que siguen para que "Armar mail resumen"
// (que corre una sola vez al final) pueda mostrar el aviso sin nodos extra.
return procesar.map((item) => ({
  json: {
    ...item.json,
    _tope_alcanzado: excedeTope,
    _total_detectado: totalDetectado,
    _procesadas: procesar.length,
  },
}));

// Se llega acá cuando "Extraer datos con IA" agotó los reintentos (429,
// 529, timeout, error de red). No hay respuesta del modelo para parsear —
// se marca directo como fallo de extracción, mismo tratamiento que un JSON
// inválido en "Parsear respuesta IA", para no perder la oferta.
const linkOriginal = $('Parsear ofertas').item.json.link;
return {
  json: {
    error_extraccion: true,
    link: linkOriginal,
    respuesta_cruda: { error: ($json && $json.error) || $json },
  },
};

let oferta;
try {
  const texto = $json.content && $json.content[0] ? $json.content[0].text : '';
  oferta = JSON.parse(texto);
} catch (e) {
  oferta = null;
}

const linkOriginal = $('Parsear ofertas').item.json.link;

if (!oferta) {
  return { json: { error_extraccion: true, link: linkOriginal, respuesta_cruda: $json } };
}

oferta.link = linkOriginal || oferta.link || null;
return { json: oferta };

// Mirror de C:\\Users\\marco\\radar-empleos\\reglas.js — si cambiás una
// regla, cambiala ahí primero, corré `node --test tests/`, y después pegala
// acá. Los tests de reglas.js son la referencia de qué tiene que pasar.
const MAX_ANIOS_TOLERADO = 3;
const MAX_POSTULANTES_BAJA_COMPETENCIA = 25;
const MAX_ANTIGUEDAD_HORAS_BAJA_COMPETENCIA = 6;
const MIN_COINCIDENCIAS_STACK = 2;
// Stack real de Marco (perfil Full Stack / Automation Engineer). Editar
// acá a mano cuando cambie el CV.
const CANDIDATO_STACK = ['react', 'node', 'express', 'javascript', 'php', 'postgres', 'supabase', 'html', 'css', 'n8n'];
const TERMINOS_EXCLUYEN_PERFIL = ['junior', 'entry level', 'entry-level', 'recent grad', 'recent graduate', 'bootcamp', 'no bootcamp'];

function normalizarEmpresaPuesto(empresa, puesto) {
  const normalizar = (texto) => (texto || '')
    .toLowerCase()
    .normalize('NFD').replace(new RegExp('[̀-ͯ]', 'g'), '')
    .replace(/\b(s\.?a\.?|s\.?r\.?l\.?|inc\.?|ltd\.?|llc\.?)\b/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
  return `${normalizar(empresa)}::${normalizar(puesto)}`;
}

function contarCoincidenciasStack(ofertaStack) {
  const stackOferta = (ofertaStack || []).map((t) => t.toLowerCase());
  return CANDIDATO_STACK.filter((tech) => stackOferta.some((t) => t.includes(tech) || tech.includes(t))).length;
}

function fraseExcluyePerfil(frasesExclusion) {
  const texto = (frasesExclusion || []).join(' ').toLowerCase();
  return TERMINOS_EXCLUYEN_PERFIL.find((t) => texto.includes(t)) || null;
}

// Dedup key única por ítem (nunca null) para que un error nunca pise ni sea
// pisado por otra fila en el appendOrUpdate por dedup_key de "Guardar en
// Sheet". sufijoUnico es param para poder testear determinísticamente en
// reglas.js — acá siempre Date.now().
function generarDedupKeyError(link, sufijoUnico) {
  const base = link || 'sin-link';
  const sufijo = sufijoUnico !== undefined ? sufijoUnico : Date.now();
  return `no_parseable::${base}::${sufijo}`;
}

try {
  const oferta = $json;

  if (oferta.error_extraccion) {
    return {
      json: {
        ...oferta,
        estado: 'NO_PARSEABLE',
        motivo: 'El modelo no devolvió JSON válido (o la llamada falló tras reintentos) — revisar a mano.',
        dedup_key: generarDedupKeyError(oferta.link),
      },
    };
  }

  const dedupKey = normalizarEmpresaPuesto(oferta.empresa, oferta.puesto);
  const vistas = $('Leer ofertas ya vistas').all().map((i) => i.json);
  const yaPostulado = vistas.some((v) => v.dedup_key === dedupKey && String(v.postulado).toLowerCase() === 'true');

  let estado, motivo;

  if (yaPostulado) {
    estado = 'DESCARTAR';
    motivo = 'Ya te postulaste a este puesto en esta empresa.';
  } else if (oferta.anios_experiencia_min > MAX_ANIOS_TOLERADO && oferta.anios_excluyente === true) {
    estado = 'DESCARTAR';
    motivo = `Pide ${oferta.anios_experiencia_min}+ años de experiencia de forma excluyente.`;
  } else if (oferta.titulo_excluyente === true) {
    estado = 'DESCARTAR';
    motivo = `Pide título (${oferta.titulo_requerido || 'sin especificar'}) de forma excluyente.`;
  } else {
    const fraseExcluyente = fraseExcluyePerfil(oferta.frases_exclusion);
    if (fraseExcluyente) {
      const cita = (oferta.frases_exclusion || []).find((f) => f.toLowerCase().includes(fraseExcluyente));
      estado = 'DESCARTAR';
      motivo = `El aviso excluye tu perfil: "${cita}"`;
    } else {
      const coincidencias = contarCoincidenciasStack(oferta.stack);
      const coincidenciaReal = coincidencias >= MIN_COINCIDENCIAS_STACK;
      const seniales = [];
      if (oferta.postulantes !== null && oferta.postulantes !== undefined && oferta.postulantes < MAX_POSTULANTES_BAJA_COMPETENCIA) seniales.push(`${oferta.postulantes} postulantes`);
      if (oferta.antiguedad_horas !== null && oferta.antiguedad_horas !== undefined && oferta.antiguedad_horas < MAX_ANTIGUEDAD_HORAS_BAJA_COMPETENCIA) seniales.push(`publicada hace ${oferta.antiguedad_horas}hs`);
      if (oferta.postulacion_rapida === true) seniales.push('postulación rápida disponible');
      const competenciaBaja = seniales.length > 0;

      if (coincidenciaReal && competenciaBaja) {
        estado = 'POSTULAR YA';
        motivo = `Stack coincide (${coincidencias} tecnologías) y competencia baja: ${seniales.join(', ')}.`;
      } else if (!coincidenciaReal) {
        estado = 'MIRAR';
        motivo = `Stack no coincide lo suficiente (${coincidencias}/${MIN_COINCIDENCIAS_STACK} tecnologías).`;
      } else {
        estado = 'MIRAR';
        motivo = 'Sin datos de competencia — incierto, no se asume baja competencia.';
      }
    }
  }

  return { json: { ...oferta, dedup_key: dedupKey, estado, motivo, stack_join: (oferta.stack || []).join(', ') } };
} catch (e) {
  // Cualquier forma inesperada de la oferta (campo con tipo raro, etc.) no
  // tira el resto del batch — se marca para revisión manual, igual que un
  // JSON inválido del modelo.
  return {
    json: {
      error_extraccion: true,
      estado: 'NO_PARSEABLE',
      motivo: `Error inesperado aplicando reglas: ${String((e && e.message) || e)} — revisar a mano.`,
      dedup_key: generarDedupKeyError($json ? $json.link : null),
      link: $json ? $json.link : null,
    },
  };
}

const items = $input.all().map((i) => i.json);

const postularYa = items.filter((o) => o.estado === 'POSTULAR YA').sort((a, b) => {
  const distA = a.horas_semanales == null ? 999 : Math.abs(a.horas_semanales - 20);
  const distB = b.horas_semanales == null ? 999 : Math.abs(b.horas_semanales - 20);
  return distA - distB; // más cerca de 20hs/semana primero — preferencia de Marco, no cambia el estado
});
const mirar = items.filter((o) => o.estado === 'MIRAR');
const noParseables = items.filter((o) => o.estado === 'NO_PARSEABLE');
const descartadas = items.filter((o) => o.estado === 'DESCARTAR');

const topeAlcanzado = items.length > 0 && items[0]._tope_alcanzado === true;
const totalDetectado = items.length > 0 ? items[0]._total_detectado : 0;
const procesadas = items.length > 0 ? items[0]._procesadas : 0;

const avisoTope = !topeAlcanzado ? '' : `
  <p style="background:#fee2e2; padding:8px; border-radius:4px;">⚠️ Tope de
  seguridad alcanzado: se detectaron ${totalDetectado} ofertas, se
  procesaron solo ${procesadas}. Revisá a mano el resto en Gmail (label
  radar-empleos).</p>`;

const filaOferta = (o) => `
  <tr>
    <td><a href="${o.link || '#'}">${o.puesto || '(sin puesto)'} — ${o.empresa || '(sin empresa)'}</a>${o.horas_semanales ? ` (${o.horas_semanales}hs/sem)` : ''}</td>
    <td>${o.motivo || ''}</td>
  </tr>`;

const filaNoParseable = (o) => `
  <tr>
    <td><a href="${o.link || '#'}">${o.link || '(sin link)'}</a></td>
    <td>${o.motivo || ''}</td>
  </tr>`;

const seccion = (titulo, lista, fila) => lista.length === 0 ? '' : `
  <h2>${titulo} (${lista.length})</h2>
  <table cellpadding="6">${lista.map(fila || filaOferta).join('')}</table>`;

const html = `
  <div style="font-family: sans-serif; max-width: 600px;">
    ${avisoTope}
    ${seccion('🟢 Postular ya', postularYa)}
    ${seccion('🟡 Mirar', mirar)}
    ${seccion('⚠️ No se pudo procesar — revisar a mano', noParseables, filaNoParseable)}
    <p>🔴 Descartadas: ${descartadas.length}</p>
  </div>`;

return [{
  json: {
    asunto: `Radar de empleos — ${postularYa.length} para postular ya`,
    html,
  },
}];

// Mirror de seguimiento.js — si cambiás una regla, cambiala ahí primero,
// corré `node --test tests/`, después pegala acá.
const DIAS_AVISO_SEGUIMIENTO = 7;
const DIAS_MARCAR_FRIA = 14;

function parseAvisos(avisosEnviados) {
  return (avisosEnviados || '').split(',').map((c) => c.trim()).filter(Boolean);
}

function diffDiasCalendario(hoy, fechaPostulacionISO) {
  const inicioHoy = Date.UTC(hoy.getUTCFullYear(), hoy.getUTCMonth(), hoy.getUTCDate());
  const [anio, mes, dia] = fechaPostulacionISO.split('-').map(Number);
  const inicioFecha = Date.UTC(anio, mes - 1, dia);
  return Math.round((inicioHoy - inicioFecha) / 86400000);
}

function calcularAvisosPostulacion(fila, hoy) {
  const avisos = parseAvisos(fila.avisos_enviados);
  if (!fila.fecha_postulacion) {
    // Regla dura: nunca asumir "hoy" si falta la fecha.
    return { incompleta: true, acciones: avisos.includes('incompleta') ? [] : ['aviso_incompleta'] };
  }
  const dias = diffDiasCalendario(hoy, fila.fecha_postulacion);
  const acciones = [];
  if (dias >= DIAS_AVISO_SEGUIMIENTO && !avisos.includes('7d')) acciones.push('draft_seguimiento_7d');
  if (dias >= DIAS_MARCAR_FRIA && !avisos.includes('14d')) acciones.push('marcar_fria_14d');
  return { incompleta: false, acciones };
}

// DRY_RUN: activar con env RADAR_SEGUIMIENTO_DRY_RUN=true en el Docker
// Compose del VPS. Con esto en true, ninguna rama de escritura real
// recibe items (todas quedan en 0 items, n8n no las ejecuta) — todo se
// redirige a "Filtrar: dry-run" -> "Imprimir dry-run", que solo loguea.
const DRY_RUN = String($env.RADAR_SEGUIMIENTO_DRY_RUN || '').toLowerCase() === 'true';
const hoy = new Date();

const filas = $('Leer ofertas ya vistas').all()
  .map((i) => i.json)
  .filter((f) => String(f.postulado).toLowerCase() === 'true');

const candidatos = [];
for (const fila of filas) {
  const { acciones } = calcularAvisosPostulacion(fila, hoy);
  for (const accion of acciones) {
    candidatos.push({
      accion,
      dedup_key: fila.dedup_key,
      empresa: fila.empresa,
      puesto: fila.puesto,
      link: fila.link,
      fecha_postulacion: fila.fecha_postulacion,
      avisos_enviados: fila.avisos_enviados || '',
    });
  }
}

if (DRY_RUN) {
  return candidatos.map((c) => ({ json: { ...c, accion_real: c.accion, accion: 'reporte_dry_run' } }));
}
return candidatos.map((c) => ({ json: c }));

// Mirror de prompts/draft_seguimiento.md — mantener sincronizado.
const SYSTEM_PROMPT = "Escribís mails cortos de seguimiento para postulaciones laborales, en\nnombre de Marco. Tono profesional, breve, sin sonar ansioso ni\ndesesperado. Nunca inventes datos que no te doy: usá solo la empresa y\nel puesto que te paso, mencionalos explícitamente los dos. 3 a 5\noraciones. No incluyas asunto (va aparte). No incluyas firma (Marco la\nagrega él antes de mandar). No prometas disponibilidad ni fechas.";

const userPrompt = `Escribí un mail corto de seguimiento para la postulación a ${$json.puesto} en ${$json.empresa}. Se postuló hace 7 días o más y no tuvo respuesta todavía.`;

return { json: { ...$json, systemPrompt: SYSTEM_PROMPT, userPrompt } };

const cuerpo = ($json.content && $json.content[0] && $json.content[0].text) || '';
if (!cuerpo) {
  // Sin texto utilizable no se crea un borrador vacío — se reintenta al
  // otro día porque avisos_enviados todavía no tiene '7d' (recién se marca
  // después de crear el borrador con éxito).
  return { json: { ...$json, _sin_contenido: true } };
}
return {
  json: {
    ...$json,
    asunto_draft: `Seguimiento — ${$json.puesto} en ${$json.empresa}`,
    cuerpo_draft: cuerpo,
  },
};

return {
  json: {
    asunto: `📨 Nuevo borrador de seguimiento — ${$json.puesto} en ${$json.empresa}`,
    html: `<p>Se creó un borrador de seguimiento para <b>${$json.puesto}</b> en <b>${$json.empresa}</b>.</p><p>Revisalo en Gmail → Borradores antes de mandarlo.</p>${$json.link ? `<p><a href="${$json.link}">Ver oferta original</a></p>` : ''}`,
  },
};

return {
  json: {
    asunto: `🥶 Se enfrió: ${$json.puesto} en ${$json.empresa}`,
    html: `<p>Pasaron 14 días sin respuesta de <b>${$json.empresa}</b> para <b>${$json.puesto}</b>. Se marcó como FRÍA en la planilla.</p>`,
  },
};

return {
  json: {
    asunto: `⚠️ Falta fecha de postulación — ${$json.puesto || '(sin puesto)'} en ${$json.empresa || '(sin empresa)'}`,
    html: `<p>Esta fila tiene <code>postulado = true</code> pero no tiene <code>fecha_postulacion</code> cargada, así que el seguimiento (7d/14d) no puede calcularse.</p><p>Completá la fecha a mano en la planilla (dedup_key: <code>${$json.dedup_key}</code>).</p>`,
  },
};

const resumen = $input.all().map((i) => `- [${i.json.accion_real}] ${i.json.puesto || '(sin puesto)'} en ${i.json.empresa || '(sin empresa)'} (dedup_key: ${i.json.dedup_key})`).join('\n');
console.log(`[Radar de empleos — dry-run seguimiento] ${$input.all().length} acción(es) que se ejecutarían hoy:\n${resumen}`);
return $input.all();

// Mirror de seguimiento.js (calcularAvisosObligacion) — mismo criterio de
// sincronización que el resto de las reglas: cambiar ahí primero.
const VENTANAS_OBLIGACION_HORAS = [72, 24, 6];

function parseAvisos(avisosEnviados) {
  return (avisosEnviados || '').split(',').map((c) => c.trim()).filter(Boolean);
}

function diffHoras(fechaLimiteISO, ahora) {
  return (new Date(fechaLimiteISO).getTime() - ahora.getTime()) / 3600000;
}

const DRY_RUN = String($env.RADAR_SEGUIMIENTO_DRY_RUN || '').toLowerCase() === 'true';
const ahora = new Date();

const filas = $input.all()
  .map((i) => i.json)
  .filter((f) => String(f.postulado).toLowerCase() === 'true' && f.fecha_limite);

const candidatos = [];
for (const fila of filas) {
  const horasRestantes = diffHoras(fila.fecha_limite, ahora);
  if (horasRestantes < 0) continue; // ya venció, no avisar de algo que ya pasó
  const avisos = parseAvisos(fila.avisos_enviados);
  for (const ventana of VENTANAS_OBLIGACION_HORAS) {
    const codigo = `${ventana}h`;
    if (horasRestantes <= ventana && !avisos.includes(codigo)) {
      candidatos.push({
        accion: `deadline_${codigo}`,
        _codigo: codigo,
        dedup_key: fila.dedup_key,
        empresa: fila.empresa,
        puesto: fila.puesto,
        tipo_obligacion: fila.tipo_obligacion || 'obligación',
        fecha_limite: fila.fecha_limite,
        avisos_enviados: fila.avisos_enviados || '',
        horas_restantes: Math.round(horasRestantes),
      });
    }
  }
}

if (DRY_RUN) {
  return candidatos.map((c) => ({ json: { ...c, accion_real: c.accion, accion: 'reporte_dry_run' } }));
}
return candidatos.map((c) => ({ json: c }));

